-- SQLite, against output/analysis.sqlite generated by src/analyze.py.
-- Fixed 90-day follow-up: invoice sequencing and eligibility use the same exclusive cutoff as Python.
WITH ranked AS (
 SELECT customer, date, ROW_NUMBER() OVER (PARTITION BY customer ORDER BY date, invoice) AS n FROM orders
), first_second AS (
 SELECT customer, MAX(CASE WHEN n=1 THEN date END) AS first_date,
        MAX(CASE WHEN n=2 THEN date END) AS second_date FROM ranked GROUP BY customer
)
SELECT COUNT(*) AS eligible_customers,
 SUM(CASE WHEN julianday(second_date)-julianday(first_date) <= 90 THEN 1 ELSE 0 END) AS repeat_90
FROM first_second WHERE datetime(first_date) <= datetime('2011-12-01', '-90 days');

-- Monthly activity, identified purchasers only.
SELECT substr(date,1,7) AS month, COUNT(DISTINCT customer) AS active_customers,
       COUNT(*) AS orders, ROUND(SUM(gross),2) AS gross
FROM orders GROUP BY 1 ORDER BY 1;
